export function toPlannerPlace(destination) {
  const sights = destination.highlights || [];
  const foods = destination.foods || [];
  const choose = (items, fallback) => items.length ? items : [fallback];
  const morningSights = choose(sights, `Explore ${destination.name}`).slice(0, 4);
  const afternoonSights = [...morningSights].reverse();
  const meals = choose(foods, 'a local seasonal meal').slice(0, 3);
  const neighbourhood = destination.name.split('&')[0].trim();
  return {
    name: destination.name,
    country: 'India',
    region: destination.region,
    highlights: destination.highlights.slice(0, 6),
    foods: destination.foods.slice(0, 4),
    bestTime: destination.bestTime,
    goodToKnow: destination.goodToKnow,
    morning: morningSights.map((sight) => `Start with ${sight}. Keep the timing flexible and check local access.`),
    lunch: meals.map((meal) => `Make time for ${meal}; ask about ingredients and choose a trusted local place.`),
    afternoon: afternoonSights.map((sight) => `Spend the afternoon around ${sight}, leaving room for a rest or a nearby detour.`),
    evening: [
      destination.eveningIdea || `Keep the evening open for a local walk and relaxed meal in ${neighbourhood}.`,
      `Choose a low-key local dinner near ${neighbourhood} and rest before the next outing.`,
      'Leave sunset flexible for weather, local customs and the day’s pace.'
    ],
    themes: [destination.tagline, `Local sights and flavours in ${neighbourhood}`, `A slower day in ${destination.region}`, 'Small discoveries, with time to enjoy them']
  };
}
